// server/routes/pantry.ts
var pantryRouter = new Hono2();
pantryRouter.get("/", (c2) => {
  const location = c2.req.query("location");
  const inventory = PantryEngine.getInventory(location);
  const restockCandidates = PantryEngine.getRestockCandidates(3);
  return c2.json({
    totalCount: inventory.length,
    urgentRestockCount: restockCandidates.length,
    items: inventory,
    restockCandidates
  });
});
pantryRouter.post("/item", async (c2) => {
  try {
    const body = await c2.req.json();
    const item = PantryEngine.addItemFromSku(body.sku, body.location, body.quantity);
    return c2.json({ success: true, item });
  } catch (err) {
    return c2.json({ error: err.message }, 400);
  }
});
pantryRouter.patch("/item/:id", async (c2) => {
  const id = c2.req.param("id");
  const body = await c2.req.json();
  const updated = PantryEngine.updateQuantity(id, body.quantity);
  if (!updated) {
    return c2.json({ error: "Item n\xE3o encontrado" }, 404);
  }
  return c2.json({ success: true, item: updated });
});
pantryRouter.delete("/item/:id", (c2) => {
  const id = c2.req.param("id");
  const ok = PantryEngine.deleteItem(id);
  return c2.json({ success: ok });
});
pantryRouter.post("/restock-to-cart", async (c2) => {
  const body = await c2.req.json().catch(() => ({}));
  const threshold = body.daysThreshold || 3;
  const supermarket = body.supermarket || "Continente";
  const candidates = PantryEngine.getRestockCandidates(threshold);
  for (const cand of candidates) {
    CartEngine.addItem({
      sku: cand.item.sku,
      quantity: cand.recommendedQuantity,
      addedBy: "predictive_restock",
      supermarket
    });
  }
  return c2.json({
    success: true,
    restockedCount: candidates.length,
    cart: CartEngine.getCart()
  });
});

