// server/routes/catalog.ts
init_modules_watch_stub();
var catalogRouter = new Hono2();
catalogRouter.get("/", async (c2) => {
  const lang = c2.req.query("lang") || "pt";
  const catalog = await c2.env.FILESYSTEM_BUCKET.get(`asualoja-sanity-data-${lang}.json`).then((o2) => o2?.json());
  if (!catalog) return c2.json([]);
  const category = c2.req.query("category");
  if (category) {
    return c2.json(catalog.filter((p2) => p2.category === category));
  }
  return c2.json(catalog);
});
catalogRouter.get("/search", async (c2) => {
  const q2 = c2.req.query("q") || "";
  const results = await VectorSearchService.searchByQuery(c2.env, q2, 10);
  return c2.json({ count: results.length, results });
});
catalogRouter.post("/vector-search", async (c2) => {
  const { query, locale, topK } = await c2.req.json();
  if (!query) {
    return c2.json({ error: "Query \xE9 obrigat\xF3ria" }, 400);
  }
  const results = await VectorSearchService.vectorSearch(c2.env, query, locale, topK);
  return c2.json({ count: results.length, results });
});
catalogRouter.get("/barcode/:ean", async (c2) => {
  const ean = c2.req.param("ean");
  const lang = c2.req.query("lang") || "pt";
  const catalog = await c2.env.FILESYSTEM_BUCKET.get(`asualoja-sanity-data-${lang}.json`).then((o2) => o2?.json());
  const product = catalog?.find((p2) => p2.ean === ean);
  if (!product) {
    return c2.json({ error: "Produto n\xE3o encontrado para este c\xF3digo de barras" }, 404);
  }
  const equivalents = await VectorSearchService.findEquivalents(c2.env, product.sku, 3);
  return c2.json({ product, equivalents });
});
catalogRouter.get("/:sku", async (c2) => {
  const sku = c2.req.param("sku");
  const lang = c2.req.query("lang") || "pt";
  const bucket = c2.env?.FILESYSTEM_BUCKET;
  if (!bucket) {
    console.error("R2 binding FILESYSTEM_BUCKET missing. Ensure you are running with wrangler dev.");
    return c2.json({ error: "Storage backend not configured" }, 500);
  }
  const catalog = await bucket.get(`asualoja-sanity-data-${lang}.json`).then((o2) => o2?.json());
  const product = catalog?.find((p2) => p2.sku === sku);
  if (!product) {
    return c2.json({ error: "Produto n\xE3o encontrado" }, 404);
  }
  const equivalents = await VectorSearchService.findEquivalents(c2.env, sku, 3);
  return c2.json({ product, equivalents });
});

